echo "--- 1mcp config: any Obsidian/mcp-tools-istefox entries? ---"
cat /Users/leon.ormes/.local/state/1mcp/mcp.resolved.json 2>/dev/null | python3 -c "
import json,sys
d = json.load(sys.stdin)
def find(obj, path=''):
    if isinstance(obj, dict):
        for k,v in obj.items():
            if 'obsidian' in k.lower() or 'mcp-tools' in k.lower() or '27200' in str(v) or '2720' in str(v):
                print(path+'/'+k, '=>', json.dumps(v)[:300])
            find(v, path+'/'+k)
    elif isinstance(obj, list):
        for i,v in enumerate(obj):
            find(v, path+f'[{i}]')
find(d)
"
echo "--- currently running mcp-remote / anything hitting 2720x ---"
